\\ Independent construction of the carried control recipes of AMD-20260926-typed
\\ (C-PLANT-M, C-PLANT-P, C-INERT, C-PLANT-PL), written by the TASK-20260928-b2f828
\\ validator from the recipe text only. ispseudoprime = BPSW screen; isprime = proof.
default(parisizemax, 2^30);
ceildiv(a,b) = (a + b - 1) \ b;
icbrt(n) = { my(x = sqrtnint(n, 3)); while(x^3 > n, x--); while((x+1)^3 <= n, x++); x };
npge(x) = { my(p = x); while(!ispseudoprime(p), p++); p };
npgt(x) = npge(x + 1);
B = 256; M0 = 3 * 2^(B-2); BL = 521; ML = 3 * 2^(BL-2);
out = List();
\\ C-PLANT-M
S = sqrtint(M0); d1 = npge(sqrtint(S)); d2 = npgt(d1); D = d1*d2; u0 = ceildiv(M0, 2*D);
u = u0; cnt = 0;
while(1, cnt++; if(ispseudoprime(u) && u != d1 && u != d2, r = 2*D*u + 1; if(ispseudoprime(r) && (r+1) % 12 == 0 && ispseudoprime((r+1)/12), break)); u++);
listput(out, ["C-PLANT-M", [S, d1, d2, D, u0, u, r, (r+1)/12, cnt, d1 - sqrtint(S), d2 - d1, u - u0, #binary(r)]]);
rM = r; uM = u; d1M = d1; d2M = d2; DM = D;
\\ C-PLANT-P
d0 = icbrt(M0/4); d = npge(d0); w0 = ceildiv(M0, 12*d); w = w0; cnt = 0;
while(1, cnt++; if(ispseudoprime(w) && w != d, r = 12*d*w - 1; if(ispseudoprime(r) && ispseudoprime((r-1)/2), break)); w++);
listput(out, ["C-PLANT-P", [d0, d, w0, w, r, (r-1)/2, cnt, d - d0, w - w0, #binary(r), #binary(d), #binary(d0)]]);
rP = r; dP = d; wP = w;
\\ C-INERT
w0 = 2^(B-4); w = w0; cnt = 0;
while(1, cnt++; if(ispseudoprime(w), r = 12*w - 1; if(ispseudoprime(r) && ispseudoprime(6*w - 1), break)); w++);
listput(out, ["C-INERT", [w0, w, r, (r-1)/2, cnt, w - w0, #binary(r)]]);
rI = r; wI = w;
\\ C-PLANT-PL
xL = icbrt(ML/4); f1 = npge(2^43); f2 = npgt(f1); f3 = npgt(f2); G = f1*f2*f3; y = ceildiv(xL, G); f4 = npge(y);
DL = G*f4; w0 = ceildiv(ML, 12*DL); w = w0; cnt = 0;
while(1, cnt++; if(ispseudoprime(w), r = 12*DL*w - 1; if(ispseudoprime(r) && ispseudoprime((r-1)/2), break)); w++);
listput(out, ["C-PLANT-PL", [xL, f1, f2, f3, G, y, f4, DL, w0, w, r, (r-1)/2, cnt, f1 - 2^43, f2 - f1, f3 - f2, f4 - y, w - w0, #binary(r), f4 > f3]]);
rL = r; wL = w;
\\ proofs (APRCL/ECPP via isprime) of every named prime
pr = [d1M, d2M, uM, rM, (rM+1)/12, dP, wP, rP, (rP-1)/2, wI, rI, 6*wI-1, f1, f2, f3, f4, wL, rL, (rL-1)/2];
proofs = vector(#pr, i, isprime(pr[i]));
listput(out, ["proofs", proofs]);
\\ constructed factorization checks
listput(out, ["factorization_checks", [rM - 1 == 2*d1M*d2M*uM, rM + 1 == 12*((rM+1)/12), rP + 1 == 12*dP*wP, rP - 1 == 2*((rP-1)/2), rI - 1 == 2*(6*wI-1), rI + 1 == 12*wI, rL + 1 == 12*f1*f2*f3*f4*wL, rL - 1 == 2*((rL-1)/2)]]);
write("/Volumes/SSD990/tmp/val-b2f828/controls_out.txt", Vec(out));
quit;

evaluate.py.source:
"""Independent evaluator for RJ1 of REVIEW-AUXIN-20260928-104724 (TASK-20260928-b2f828).

Written from the governing text only (typed definitions, D3, narrow BINS-EXACT and
corrective.bin_by_status, gated spans G-GATE1/G-BND1/G-BND3). mpmath at 170 digits.
"""
import json, itertools, hashlib, sys
from mpmath import mp, mpf, sqrt, log

mp.dps = 170
TAU = mpf(10) ** -45
TIE = mpf(10) ** -100
C = json.load(open('/Volumes/SSD990/tmp/val-b2f828/controls.json'))


def lg2(x):
    return log(x) / log(2)


def T(b, m, d):
    return sqrt(mpf(m) / d) + (sqrt(mpf(d)) if b == 'minus' else mpf(d))


def e_of(b, r, m, d):
    return lg2(T(b, m, d)) / lg2(r)


def F(b, r):
    if b == 'minus':
        return (1 + lg2(r - 1) / 4) / lg2(r)
    return (lg2(3) - mpf(2) / 3 + lg2(r + 1) / 3) / lg2(r)


def Cb(b, r, m):
    return lg2(sqrt(mpf(m)) + 1) / lg2(r)


def depth(b, r, m, e):
    return (Cb(b, r, m) - e) / (Cb(b, r, m) - F(b, r))


def flag(s):
    return abs(s - mpf(1) / 4) <= TAU or abs(s - mpf(3) / 4) <= TAU


def exact_bin(s):
    # narrow span BINS-EXACT, rules applied in order
    if flag(s):
        return 'INTERMEDIATE' if abs(s - mpf(3) / 4) <= TAU else 'NEAR_CEILING'
    if s >= mpf(3) / 4 + TAU:
        return 'NEAR_FLOOR'
    if s <= mpf(1) / 4 - TAU:
        return 'NEAR_CEILING'
    return 'INTERMEDIATE'


def bound_bins(s):
    # narrow corrective.bin_by_status, BOUND case
    f = flag(s)
    if (not f) and s >= mpf(3) / 4 + TAU:
        return 'NEAR_FLOOR', 'NEAR_FLOOR', f
    return 'UNDETERMINED', exact_bin(s), f


def divisors_from(pp):
    ds = [1]
    for p, k in pp:
        ds = [d * p ** i for d in ds for i in range(k + 1)]
    return sorted(set(ds))


def minimise(b, r, m, cands):
    vals = {d: e_of(b, r, m, d) for d in cands}
    estar = min(vals.values())
    tied = sorted(d for d, v in vals.items() if v - estar <= TIE * estar)
    return tied[0], vals[tied[0]], tied


def eval_exact(b, r, pp):
    m = r - 1 if b == 'minus' else r + 1
    ds = divisors_from(pp)
    assert all(m % d == 0 for d in ds) and max(ds) == m
    d, e, tied = minimise(b, r, m, ds)
    s = depth(b, r, m, e)
    bn = exact_bin(s)
    return dict(status='EXACT', minimiser=d, tied=tied, e=e, F=F(b, r), gap=e - F(b, r), s=s,
                bin=bn, bin_at_least=bn, boundary_flag=flag(s), n_divisors=len(ds))


def eval_bound(b, r, Fpp, parts):
    m = r - 1 if b == 'minus' else r + 1
    Fb = 1
    for p, k in Fpp:
        Fb *= p ** k
    prod = Fb
    for P in parts:
        prod *= P
    assert prod == m, 'declared state does not multiply to m_b'
    es = divisors_from(Fpp)
    W = set()
    for k in range(len(parts) + 1):
        for S in itertools.combinations(parts, k):
            ps = 1
            for P in S:
                ps *= P
            for e in es:
                W.add(e * ps)
    W = sorted(W)
    assert all(m % w == 0 for w in W)
    d, ub, tied = minimise(b, r, m, W)
    s = depth(b, r, m, ub)
    bn, bal, fl = bound_bins(s)
    return dict(status='BOUND', W=W, witness=d, tied=tied, upper=ub, lower=F(b, r), s=s,
                bin=bn, bin_at_least=bal, boundary_flag=fl)


def gate1(returned, expected):
    """Gate 1 after G-GATE1: status, witness set, witness, bin, bin_at_least, boundary_flag
    must equal the expected values exactly (no 'where stated' carve-out)."""
    keys = ['status', 'W', 'witness', 'bin', 'bin_at_least', 'boundary_flag']
    return all(k in returned and returned[k] == expected[k] for k in keys)


def gate1_narrow(returned, expected, bin_at_least_stated):
    """Gate 1 as held in typed text before G-GATE1 ('bin_at_least (where stated)')."""
    keys = ['status', 'W', 'witness', 'bin', 'boundary_flag']
    if bin_at_least_stated:
        keys.append('bin_at_least')
    return all(k in returned and returned[k] == expected[k] for k in keys)


def n4_met(returned, fixed):
    keys = ['status', 'W', 'witness', 'bin', 'bin_at_least', 'boundary_flag']
    return any(returned.get(k, None) != fixed[k] for k in keys)


def main():
    M, P, I, L = C['C-PLANT-M'], C['C-PLANT-P'], C['C-INERT'], C['C-PLANT-PL']
    res = {'controls_exact': {}, 'c_bound': {}, 'own_states': {}, 'gating_tests': {}, 'narrow_contrast': {}}
    # ---- exact evaluations of the four construction controls (R-D4)
    rM, d1, d2, u, v = M['r'], M['d1'], M['d2'], M['u'], M['v']
    D = d1 * d2
    rP, d, w, qP = P['r'], P['d'], P['w'], P['q']
    rI, wI, qI = I['r'], I['w'], I['q']
    rL, qL = L['r'], L['q']
    f1, f2, f3, f4, wL, DL = L['f1'], L['f2'], L['f3'], L['f4'], L['w'], L['D_L']
    ex = res['controls_exact']
    ex['C-PLANT-M'] = {'minus': eval_exact('minus', rM, [(2, 1), (d1, 1), (d2, 1), (u, 1)]),
                       'plus': eval_exact('plus', rM, [(2, 2), (3, 1), (v, 1)])}
    ex['C-PLANT-P'] = {'plus': eval_exact('plus', rP, [(2, 2), (3, 1), (d, 1), (w, 1)]),
                       'minus': eval_exact('minus', rP, [(2, 1), (qP, 1)])}
    ex['C-INERT'] = {'minus': eval_exact('minus', rI, [(2, 1), (qI, 1)]),
                     'plus': eval_exact('plus', rI, [(2, 2), (3, 1), (wI, 1)])}
    ex['C-PLANT-PL'] = {'plus': eval_exact('plus', rL, [(2, 2), (3, 1), (f1, 1), (f2, 1), (f3, 1), (f4, 1), (wL, 1)]),
                        'minus': eval_exact('minus', rL, [(2, 1), (qL, 1)])}
    g = {}
    x = ex['C-PLANT-M']
    g['C-PLANT-M'] = {'minus_minimiser_in_{D,(r-1)/D}': x['minus']['minimiser'] in (D, (rM - 1) // D),
                      'minus_gap_in_[0,1e-6]': (x['minus']['gap'] >= -mpf(10) ** -45) and x['minus']['gap'] <= mpf(10) ** -6,
                      'minus_bin_NEAR_FLOOR': x['minus']['bin'] == 'NEAR_FLOOR',
                      'plus_bin_NEAR_CEILING': x['plus']['bin'] == 'NEAR_CEILING'}
    x = ex['C-PLANT-P']
    g['C-PLANT-P'] = {'plus_minimiser_eq_d': x['plus']['minimiser'] == d,
                      'plus_gap_in_[0,1e-6]': (x['plus']['gap'] >= -mpf(10) ** -45) and x['plus']['gap'] <= mpf(10) ** -6,
                      'plus_bin_NEAR_FLOOR': x['plus']['bin'] == 'NEAR_FLOOR',
                      'minus_bin_NEAR_CEILING': x['minus']['bin'] == 'NEAR_CEILING'}
    x = ex['C-INERT']
    g['C-INERT'] = {'minus_minimiser_smaller_of_{2,q}': x['minus']['minimiser'] == min(2, qI),
                    'minus_bin_NEAR_CEILING': x['minus']['bin'] == 'NEAR_CEILING',
                    'plus_minimiser_largest_divisor_of_12': x['plus']['minimiser'] == 12,
                    'plus_bin_NEAR_CEILING': x['plus']['bin'] == 'NEAR_CEILING'}
    x = ex['C-PLANT-PL']
    g['C-PLANT-PL'] = {'plus_minimiser_eq_D_L': x['plus']['minimiser'] == DL,
                       'plus_gap_in_[0,1e-6]': (x['plus']['gap'] >= -mpf(10) ** -45) and x['plus']['gap'] <= mpf(10) ** -6,
                       'plus_bin_NEAR_FLOOR': x['plus']['bin'] == 'NEAR_FLOOR',
                       'minus_minimiser_smaller_of_{2,q}': x['minus']['minimiser'] == 2,
                       'minus_bin_NEAR_CEILING': x['minus']['bin'] == 'NEAR_CEILING',
                       'plus_part_after_F0_bits_gt_272': (f1 * f2 * f3 * f4 * wL).bit_length() > 272}
    res['control_gates_text_determinable'] = g
    # ---- C-BOUND declared states
    mM = rM - 1
    mP = rP + 1
    cb = res['c_bound']
    cb['BND-1'] = eval_bound('minus', rM, [(2, 1), (u, 1)], [D])
    cb['BND-2'] = eval_bound('minus', rM, [(2, 1)], [d1 * d2 * u])
    cb['BND-3'] = eval_bound('plus', rP, [(2, 1)], [2 * d, 3 * w])
    exp = {
        'BND-1': dict(status='BOUND', W=sorted({e for e in divisors_from([(2, 1), (u, 1)])} | {e * D for e in divisors_from([(2, 1), (u, 1)])}),
                      witness=min(D, 2 * u), bin='NEAR_FLOOR', bin_at_least='NEAR_FLOOR', boundary_flag=False),
        'BND-2': dict(status='BOUND', W=sorted({1, 2, mM // 2, mM}), witness=2, bin='UNDETERMINED',
                      bin_at_least='NEAR_CEILING', boundary_flag=False),
        'BND-3': dict(status='BOUND', W=sorted({1, 2, 2 * d, 4 * d, 3 * w, 6 * w, 6 * d * w, 12 * d * w}), witness=2 * d,
                      bin='NEAR_FLOOR', bin_at_least='NEAR_FLOOR', boundary_flag=False),
    }
    closed = {'BND-1': (e_of('minus', rM, mM, min(D, 2 * u)), F('minus', rM)),
              'BND-2': (e_of('minus', rM, mM, 2), F('minus', rM)),
              'BND-3': (e_of('plus', rP, mP, 2 * d), F('plus', rP))}
    for k in cb:
        st = cb[k]
        st['expected_after_gated'] = {kk: (vv if kk != 'W' else len(vv)) for kk, vv in exp[k].items()}
        st['gate1_pass'] = gate1(st, exp[k])
        st['gate2_bounds_within_1e-50'] = abs(st['upper'] - closed[k][0]) <= mpf(10) ** -50 and abs(st['lower'] - closed[k][1]) <= mpf(10) ** -50
        st['floor_invariant'] = st['upper'] >= st['lower'] - mpf(10) ** -45
        # value bin_by_status assigns on the witnessed depth (N4's "value this text fixes")
        bb = bound_bins(st['s'])
        st['bin_by_status_value'] = {'bin': bb[0], 'bin_at_least': bb[1], 'boundary_flag': bb[2]}
        st['expected_block_equals_bin_by_status'] = (bb[0] == exp[k]['bin'] and bb[1] == exp[k]['bin_at_least'] and bb[2] == exp[k]['boundary_flag'])
    cb['BND-1']['consistency_with_C-PLANT-M_exact_within_1e-50'] = abs(cb['BND-1']['upper'] - ex['C-PLANT-M']['minus']['e']) <= mpf(10) ** -50
    cb['BND-1']['D_vs_2u'] = 'D<2u' if D < 2 * u else ('D>2u' if D > 2 * u else 'equal')
    # ---- reviewer-constructed NEAR_FLOOR BOUND states
    own = res['own_states']
    own['OWN-1'] = dict(row_and_branch='C-PLANT-M minus', declared_state='F = 2*d1*u (2^1, d1^1, u^1); parts [d2]',
                        **eval_bound('minus', rM, [(2, 1), (d1, 1), (u, 1)], [d2]))
    own['OWN-2'] = dict(row_and_branch='C-PLANT-PL plus', declared_state='F = 12*w (2^2, 3^1, w^1); parts [f1*f2, f3*f4]',
                        **eval_bound('plus', rL, [(2, 2), (3, 1), (wL, 1)], [f1 * f2, f3 * f4]))
    own['OWN-3'] = dict(row_and_branch='C-PLANT-P plus', declared_state='F = 12 (2^2, 3^1); parts [d, w]',
                        **eval_bound('plus', rP, [(2, 2), (3, 1)], [d, w]))
    for k, st in own.items():
        st['expected_from_bin_by_status'] = {'bin': st['bin'], 'bin_at_least': st['bin_at_least'], 'boundary_flag': st['boundary_flag']}
    # ---- gating tests (iv) and one-outcome check (ii)/(iii)
    gt = res['gating_tests']
    allst = {**{k: (cb[k], exp[k]) for k in cb},
             **{k: (own[k], dict(status='BOUND', W=own[k]['W'], witness=own[k]['witness'], bin=own[k]['bin'],
                                 bin_at_least=own[k]['bin_at_least'], boundary_flag=own[k]['boundary_flag'])) for k in own}}
    wrong = {'NEAR_FLOOR': 'INTERMEDIATE', 'NEAR_CEILING': 'INTERMEDIATE', 'INTERMEDIATE': 'NEAR_CEILING'}
    for k, (st, ex_) in allst.items():
        correct = {kk: st[kk] for kk in ['status', 'W', 'witness', 'bin', 'bin_at_least', 'boundary_flag']}
        absent = {kk: vv for kk, vv in correct.items() if kk != 'bin_at_least'}
        wrongv = dict(correct, bin_at_least=wrong[correct['bin_at_least']])
        nullv = dict(correct, bin_at_least=None)
        rows = {}
        for lab, ret in [('correct', correct), ('bin_at_least_absent', absent), ('bin_at_least_null', nullv), ('bin_at_least_wrong', wrongv)]:
            gp = gate1(ret, ex_)
            n4 = n4_met(ret, ex_)
            rows[lab] = {'gate1': 'pass' if gp else 'fail', 'N4_met': n4,
                         'one_outcome': (gp and not n4) or ((not gp) and n4)}
        gt[k] = rows
    # ---- contrast: the same tests under the pre-gated text (narrow), to show the harness sees DF-N1
    nc = res['narrow_contrast']
    stated_narrow = {'BND-1': False, 'BND-2': True, 'BND-3': False}
    for k in cb:
        st, ex_ = cb[k], exp[k]
        correct = {kk: st[kk] for kk in ['status', 'W', 'witness', 'bin', 'bin_at_least', 'boundary_flag']}
        absent = {kk: vv for kk, vv in correct.items() if kk != 'bin_at_least'}
        rows = {}
        for lab, ret in [('correct', correct), ('bin_at_least_absent_E0', absent)]:
            gp = gate1_narrow(ret, ex_, stated_narrow[k])
            n4 = n4_met(ret, ex_)
            rows[lab] = {'gate1': 'pass' if gp else 'fail', 'N4_met': n4, 'one_outcome': (gp and not n4) or ((not gp) and n4)}
        nc[k] = rows
    return res


def ser(o):
    if isinstance(o, dict):
        return {k: ser(v) for k, v in o.items()}
    if isinstance(o, (list, tuple)):
        return [ser(v) for v in o]
    if isinstance(o, bool) or o is None or isinstance(o, str):
        return o
    if isinstance(o, int):
        return str(o)
    try:
        return mp.nstr(o, 60)
    except Exception:
        return str(o)


if __name__ == '__main__':
    r = main()
    json.dump(ser(r), open('/Volumes/SSD990/tmp/val-b2f828/rj1_results.json', 'w'), indent=1)
    print('written')

fp_check.py.source:
"""R-NJ1 / ER-6 check: rebuild FP from the local pinned sources with the typed
parse rules (PR-SP800, PR-SEC2, PR-RFC5639), apply mutation M-FP, and check the
construction-control r values against FP under the ER-6 reading."""
import json
import re
import sys

import sympy

SPECS = sys.argv[1]
WS = re.compile(r"\s+")


def strip_ws(s):
    return WS.sub("", s)


def lines(name):
    with open(f"{SPECS}/{name}", encoding="utf-8", errors="replace") as fh:
        return fh.read().split("\n")


def pr_sp800(block_no, label):
    L = lines("sp800-186.txt")
    start = next(i for i, x in enumerate(L) if x.strip() == block_no)
    end = next((i for i in range(start + 1, len(L))
                if re.fullmatch(r"[0-9]+(\.[0-9]+)*\.", L[i].strip())), len(L))
    blk = L[start:end]
    li = next(i for i, x in enumerate(blk) if x.lstrip().startswith(label + ":"))
    text = blk[li].lstrip()[len(label) + 1:]
    tail = []
    for j in range(li + 1, len(blk)):
        if re.match(r"[A-Za-z]{1,4}:", blk[j].strip()):
            break
        tail.append(blk[j])
    full = "\n".join([text] + tail)
    paren = full.find("(")
    span = full if paren < 0 else full[:paren]
    dec = strip_ws(span).replace("\\", "")
    dec_clean = bool(dec) and dec.isdigit()
    hexv = None
    rep = {}
    if paren >= 0:
        after = strip_ws(full[paren + 1:])
        if after.startswith("=0x"):
            h = after[3:].split(")")[0]
            if h and re.fullmatch(r"[0-9A-Fa-f]+", h):
                hexv = int(h, 16)
    if hexv is not None:
        rep["used"] = "hex"
        if dec_clean:
            if len(dec) == len(str(hexv)):
                if int(dec) != hexv:
                    raise SystemExit("locator_failure")
            else:
                rep["ignored"] = "decimal_span_not_a_literal"
        elif dec:
            rep["ignored"] = "decimal contaminated"
        return hexv, rep
    if dec_clean:
        rep["used"] = "decimal"
        return int(dec), rep
    raise SystemExit("locator_failure")


def pr_sec2(curve, label):
    L = lines("sec2-v2.txt")
    start = next(i for i, x in enumerate(L)
                 if re.fullmatch(r"[0-9]+(\.[0-9]+)+RecommendedParameters" + curve, strip_ws(x)))
    end = next((i for i in range(start + 1, len(L)) if "RecommendedParameters" in L[i]), len(L))
    blk = L[start:end]
    for i, x in enumerate(blk):
        if x.strip() != label:
            continue
        j = i + 1
        while j < len(blk) and not blk[j].strip():
            j += 1
        if j < len(blk) and blk[j].lstrip().startswith("="):
            first = strip_ws(blk[j].lstrip()[1:])
            k = j + 1
            if not first:
                while not blk[k].strip():
                    k += 1
                first = strip_ws(blk[k])
                k += 1
            assert re.fullmatch(r"[0-9A-Fa-f]+", first)
            vals = [first]
            while k < len(blk):
                s = strip_ws(blk[k])
                if re.fullmatch(r"[0-9A-Fa-f]{4,}", s):
                    vals.append(s)
                    k += 1
                else:
                    break
            return int("".join(vals), 16)
    raise SystemExit("locator_failure")


def pr_rfc5639(curve, label):
    L = lines("rfc5639.txt")
    start = next(i for i, x in enumerate(L) if x.strip() == f"Curve-ID: {curve}")
    end = next((i for i in range(start + 1, len(L))
                if L[i].strip().startswith(("Curve-ID:", "#Twisted"))
                or re.match(r"[0-9]+(\.[0-9]+)*\.\s", L[i].strip())), len(L))
    blk = L[start:end]
    i = next(i for i, x in enumerate(blk)
             if x.strip().startswith(label + " =") or x.strip() == label + " =")
    vals = [strip_ws(blk[i].split("=", 1)[1])]
    for x in blk[i + 1:]:
        s = strip_ws(x)
        if s and re.fullmatch(r"[0-9A-Fa-f]+", s):
            vals.append(s)
        else:
            break
    return int("".join(vals), 16)


extracted = {}
reps = {}
for row, blk in [("NIST-P-224", "3.2.1.2."), ("NIST-P-256", "3.2.1.3."),
                 ("NIST-P-384", "3.2.1.4."), ("NIST-P-521", "3.2.1.5."),
                 ("Ed25519-L", "3.2.3.1.")]:
    extracted[row], reps[row] = pr_sp800(blk, "p")
extracted["secp256k1"] = pr_sec2("secp256k1", "p")
extracted["brainpoolP256r1"] = pr_rfc5639("brainpoolP256r1", "p")
extracted["brainpoolP384r1"] = pr_rfc5639("brainpoolP384r1", "p")

CF1 = 2**255 - 19
CF2 = 2**256 - 2**224 + 2**192 + 2**96 - 1
FP = set(extracted.values()) | {CF1, CF2}
MFP = {CF1, CF2}

out = {
    "rows_extracted_locally": {k: {"bits": v.bit_length(), "prime": bool(sympy.isprime(v)),
                                   "representation": reps.get(k)} for k, v in extracted.items()},
    "rows_not_extracted_here": {
        "BN254-r": "pinned remote revision not retrieved; field prime is 254 bits by the EIP-197 curve definition (recalled)",
        "BLS12-381-r": "pinned remote revision not retrieved; field prime is 381 bits (recalled)",
    },
    "ER-7_cross_checks": {
        "CF-1_equals_Ed25519-L_p": extracted["Ed25519-L"] == CF1,
        "CF-1_representation_selected_by_PR-SP800": reps["Ed25519-L"],
        "CF-2_equals_NIST-P-256_p": extracted["NIST-P-256"] == CF2,
        "CF-2_representation_selected_by_PR-SP800": reps["NIST-P-256"],
    },
    "M-FP": {},
}
for row, p in extracted.items():
    out["M-FP"][f"CF-X-{row}"] = {
        "under_FP_reasons": ["field_prime"] if p in FP else [],
        "under_M-FP_reasons": ["field_prime"] if p in MFP else [],
        "gate_under_M-FP": "pass" if p in MFP else "fail (N2)",
    }
out["M-FP_fails_a_declared_control"] = any(
    v["gate_under_M-FP"].startswith("fail") for v in out["M-FP"].values())

controls = json.load(open("controls.json"))
out["ER-6_control_r_vs_FP"] = {}
for c in ("C-PLANT-M", "C-PLANT-P", "C-INERT", "C-PLANT-PL"):
    r = int(controls[c]["r"])
    out["ER-6_control_r_vs_FP"][c] = {
        "bits": r.bit_length(),
        "in_FP_local": r in FP,
        "bit_length_excludes_unretrieved_rows": r.bit_length() not in (254, 381),
        "prime": bool(sympy.isprime(r)),
        "clause1_2_reasons": (["field_prime"] if r in FP else []) + ([] if sympy.isprime(r) else ["not_prime"]),
    }
json.dump(out, open("fp_results.json", "w"), indent=1)
print(json.dumps(out, indent=1))

