"""Library-free ECPP certificate verifier (stdlib only; imports nothing from PARI).
Input: PARI primecert output [[N, t, s, a4, [x, y]], ...]. Each step proves N prime
given q = (N + 1 - t) / s prime, via Goldwasser-Kilian / Atkin-Morain: a point P on
y^2 = x^3 + a4 x + b over Z/N with [m]P = O and [s]P != O, all denominators invertible,
and q > (c + 1)^2 where c is the least integer with c^4 >= N. The terminal q is
proved by Pratt (Lucas) with factorisation by trial division."""
import json
import math
import re
import sys


class NonInvertible(Exception):
    pass


def inv(a, n):
    a %= n
    if math.gcd(a, n) != 1:
        raise NonInvertible
    return pow(a, -1, n)


def add(P, Q, a, n):
    if P is None:
        return Q
    if Q is None:
        return P
    x1, y1 = P
    x2, y2 = Q
    if (x1 - x2) % n == 0:
        if (y1 + y2) % n == 0:
            return None
        lam = (3 * x1 * x1 + a) * inv(2 * y1, n) % n
    else:
        lam = (y2 - y1) * inv(x2 - x1, n) % n
    x3 = (lam * lam - x1 - x2) % n
    return (x3, (lam * (x1 - x3) - y1) % n)


def mul(k, P, a, n):
    R = None
    while k:
        if k & 1:
            R = add(R, P, a, n)
        P = add(P, P, a, n)
        k >>= 1
    return R


def least_c(N):
    c = math.isqrt(math.isqrt(N))
    while c ** 4 < N:
        c += 1
    while c > 0 and (c - 1) ** 4 >= N:
        c -= 1
    return c


def trial_factor(n):
    f, d = {}, 2
    while d * d <= n:
        while n % d == 0:
            f[d] = f.get(d, 0) + 1
            n //= d
        d += 1 if d == 2 else 2
    if n > 1:
        f[n] = f.get(n, 0) + 1
    return f


def pratt(q):
    if q < 2:
        return False
    if q in (2, 3):
        return True
    fs = trial_factor(q - 1)
    for g in range(2, q):
        if pow(g, q - 1, q) != 1:
            return False
        if all(pow(g, (q - 1) // p, q) != 1 for p in fs):
            return all(pratt(p) for p in fs if p != q)
    return False


def verify(cert):
    steps = []
    prev_q = None
    for N, t, s, a, (x, y) in cert:
        if prev_q is not None and N != prev_q:
            return False, steps + [{"error": "chain break"}]
        m = N + 1 - t
        if m % s:
            return False, steps + [{"error": "s does not divide m"}]
        q = m // s
        c = least_c(N)
        b = (y * y - x * x * x - a * x) % N
        ok = math.gcd(N, 6) == 1 and math.gcd((4 * a ** 3 + 27 * b * b) % N, N) == 1
        ok = ok and q > (c + 1) ** 2
        try:
            P = (x % N, y % N)
            ok = ok and mul(m, P, a, N) is None and mul(s, P, a, N) is not None
        except NonInvertible:
            ok = False
        steps.append({"N_bits": N.bit_length(), "q_bits": q.bit_length(), "ok": ok})
        if not ok:
            return False, steps
        prev_q = q
    term = pratt(prev_q)
    steps.append({"terminal_q_bits": prev_q.bit_length(), "pratt_ok": term})
    return term, steps


if __name__ == "__main__":
    raw = open(sys.argv[1]).read()
    ints = [int(v) for v in re.findall(r"-?\d+", raw)]
    cert = [(ints[i], ints[i + 1], ints[i + 2], ints[i + 3], (ints[i + 4], ints[i + 5]))
            for i in range(0, len(ints), 6)]
    N0 = int(open(sys.argv[2]).read().strip())
    ok, steps = verify(cert)
    res = {"first_N_matches_input": cert[0][0] == N0, "N_bits": N0.bit_length(),
           "chain_length": len(cert), "verified": ok and cert[0][0] == N0, "steps": steps}
    # negative control: a tampered certificate must fail
    bad = list(cert)
    N, t, s, a, (x, y) = bad[0]
    bad[0] = (N, t + 2, s, a, (x, y))
    res["tampered_trace_rejected"] = not verify(bad)[0]
    json.dump(res, open("cert_verify.json", "w"), indent=1)
    print(json.dumps(res, indent=1))
